@page "/dispatcher"
@attribute [Microsoft.AspNetCore.Authorization.Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto

<PageTitle>Dispatcher Dashboard</PageTitle>

<h3>Shipment Dashboard</h3>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-primary" @onclick="ShowCreateForm">
            + New Shipment
        </button>
    </div>
</div>

@if (showCreate)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5>Create Shipment</h5>
            <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="createShipment">
                <DataAnnotationsValidator />
                <div class="row g-2">
                    <div class="col-md-3">
                        <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                    </div>
                    <div class="col-md-3">
                        <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                    </div>
                    <div class="col-md-3">
                        <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-2">
                        <input type="number" step="0.1" class="form-control" placeholder="Weight (kg)" @bind="newShipment.WeightKg" />
                    </div>
                </div>
                <div class="row g-2 mt-2">
                    <div class="col-md-4">
                        <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                    </div>
                    <div class="col-md-3">
                        <label class="form-label small">Est. Delivery</label>
                        <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                    </div>
                    <div class="col-md-2 d-flex align-items-end">
                        <button type="submit" class="btn btn-success me-2">Create</button>
                        <button type="button" class="btn btn-secondary" @onclick="() => showCreate = false">Cancel</button>
                    </div>
                </div>
            </EditForm>
        </div>
    </div>
}

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Customer</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td><code>@shipment.TrackingNumber</code></td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                    </td>
                    <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                    <td>@shipment.CustomerEmail</td>
                    <td>
                        @if (editingId == shipment.Id)
                        {
                            <select class="form-select form-select-sm d-inline-block w-auto" @bind="editStatus">
                                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@s">@s</option>
                                }
                            </select>
                            <button class="btn btn-sm btn-success" @onclick="() => SaveStatus(shipment)">Save</button>
                            <button class="btn btn-sm btn-secondary" @onclick="() => editingId = null">Cancel</button>
                        }
                        else
                        {
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(shipment)">
                                Update Status
                            </button>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<Shipment>? shipments;
    private string filterText = "";
    private string statusFilter = "";
    private int? editingId;
    private ShipmentStatus editStatus;
    private bool showCreate;
    private Shipment newShipment = new() { EstimatedDelivery = DateTime.Now.AddDays(5) };

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private IEnumerable<Shipment> FilteredShipments =>
        shipments!.Where(s =>
            (string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter));

    private void StartEdit(Shipment shipment)
    {
        editingId = shipment.Id;
        editStatus = shipment.Status;
    }

    private async Task SaveStatus(Shipment shipment)
    {
        await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, new ShipmentUpdateDto { Status = editStatus });
        shipment.Status = editStatus;
        editingId = null;
    }

    private void ShowCreateForm()
    {
        newShipment = new Shipment { EstimatedDelivery = DateTime.Now.AddDays(5) };
        showCreate = true;
    }

    private async Task CreateShipment()
    {
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments!.Insert(0, created);
        showCreate = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/track"
@rendermode InteractiveAuto

<PageTitle>Track Shipment</PageTitle>

<h3>Track Your Shipment</h3>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001)"
                   @bind="trackingNumber" @onkeyup="HandleKeyUp" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (searched && shipment == null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedNumber</strong>. Please check and try again.
    </div>
}

@if (shipment != null)
{
    <div class="card">
        <div class="card-header d-flex justify-content-between">
            <span><strong>Tracking:</strong> @shipment.TrackingNumber</span>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Description</dt>
                        <dd>@shipment.Description</dd>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                        <dt>Weight</dt>
                        <dd>@shipment.WeightKg kg</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd class="fw-bold text-primary">@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</dd>
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <dt>Actual Delivery</dt>
                            <dd class="text-success">@shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</dd>
                        }
                    </dl>
                </div>
            </div>

            <h5 class="mt-3">Shipment Progress</h5>
            <div class="progress" style="height: 30px;">
                <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                     role="progressbar"
                     style="width: @GetProgressPercent(shipment.Status)%"
                     aria-valuenow="@GetProgressPercent(shipment.Status)"
                     aria-valuemin="0" aria-valuemax="100">
                    @shipment.Status
                </div>
            </div>
        </div>
    </div>
}

<AuthorizeView>
    <Authorized>
        <div class="mt-5">
            <h4>My Shipments</h4>
            <button class="btn btn-outline-secondary btn-sm mb-2" @onclick="LoadMyShipments">
                Refresh My Shipments
            </button>
            @if (myShipments != null)
            {
                @if (myShipments.Count == 0)
                {
                    <p class="text-muted">No shipments found for your account.</p>
                }
                else
                {
                    <div class="list-group">
                        @foreach (var s in myShipments)
                        {
                            <button class="list-group-item list-group-item-action d-flex justify-content-between align-items-center"
                                    @onclick="() => SelectShipment(s)">
                                <div>
                                    <strong>@s.TrackingNumber</strong> — @s.Description
                                    <br /><small class="text-muted">@s.Origin → @s.Destination</small>
                                </div>
                                <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                            </button>
                        }
                    </div>
                }
            }
        </div>
    </Authorized>
</AuthorizeView>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;
    [CascadingParameter] private Task<AuthenticationState>? AuthState { get; set; }

    private string trackingNumber = "";
    private string searchedNumber = "";
    private Shipment? shipment;
    private bool searched;
    private bool isLoading;
    private List<Shipment>? myShipments;

    protected override async Task OnInitializedAsync()
    {
        await LoadMyShipments();
    }

    private async Task HandleKeyUp(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searched = true;
        isLoading = false;
    }

    private async Task LoadMyShipments()
    {
        if (AuthState == null) return;
        var state = await AuthState;
        var email = state.User.Identity?.Name;
        if (!string.IsNullOrEmpty(email))
        {
            myShipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
        }
    }

    private void SelectShipment(Shipment s)
    {
        shipment = s;
        trackingNumber = s.TrackingNumber;
        searched = true;
    }

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 50,
        ShipmentStatus.Returned => 100,
        _ => 0
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-warning",
        ShipmentStatus.Returned => "bg-danger",
        _ => "bg-primary"
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-dark",
        _ => "bg-secondary"
    };
}

