using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;
using ShipmentTracker.Data.Entities;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (ApplicationDbContext db) =>
        {
            var entities = await db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync();
            return entities.Select(MapToDto);
        }).RequireAuthorization("DispatcherPolicy");

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var entity = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            return entity is null ? Results.NotFound() : Results.Ok(MapToDto(entity));
        }).AllowAnonymous();

        group.MapGet("/customer/{email}", async (string email, ApplicationDbContext db) =>
        {
            var entities = await db.Shipments
                .Where(s => s.CustomerEmail == email)
                .OrderByDescending(s => s.ShippedDate)
                .ToListAsync();
            return entities.Select(MapToDto);
        });

        group.MapPut("/{id}/status", async (int id, ShipmentUpdateDto update, ApplicationDbContext db) =>
        {
            var entity = await db.Shipments.FindAsync(id);
            if (entity is null) return Results.NotFound();

            entity.Status = (int)update.Status;
            if (update.EstimatedDelivery.HasValue)
                entity.EstimatedDelivery = update.EstimatedDelivery.Value;
            if (update.Status == ShipmentStatus.Delivered)
                entity.ActualDelivery = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok(MapToDto(entity));
        }).RequireAuthorization("DispatcherPolicy");

        group.MapPost("/", async (Shipment dto, ApplicationDbContext db) =>
        {
            var entity = new ShipmentEntity
            {
                TrackingNumber = $"TRK-{Guid.NewGuid().ToString()[..8].ToUpper()}",
                Origin = dto.Origin,
